-- JANTA BOL PHASE 2 additive migration. Run in Supabase SQL Editor after Phase-1 schema.
create extension if not exists pgcrypto;
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid,action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists analytics_events(id bigint generated by default as identity primary key,article_id uuid references articles(id) on delete set null,event_type text not null check(event_type in('view','share')),created_at timestamptz not null default now());
create index if not exists analytics_events_article_idx on analytics_events(article_id,created_at desc);
create or replace view article_stats as select a.id article_id,a.title,count(e.id) filter(where e.event_type='view')::bigint views,count(e.id) filter(where e.event_type='share')::bigint shares from articles a left join analytics_events e on e.article_id=a.id group by a.id,a.title;
create table if not exists social_distribution(article_id uuid primary key references articles(id) on delete cascade,enabled boolean not null default false,facebook boolean not null default false,instagram boolean not null default false,whatsapp boolean not null default false,youtube boolean not null default false,caption text not null default '',status jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists reporters(id uuid primary key default gen_random_uuid(),name text not null,contact text,active boolean not null default true,live_permission boolean not null default false,created_at timestamptz not null default now());
create table if not exists live_sessions(id uuid primary key default gen_random_uuid(),article_id uuid references articles(id) on delete set null,reporter_id uuid references reporters(id) on delete set null,headline text not null default '',active boolean not null default false,requested_at timestamptz not null default now(),approved_at timestamptz,ended_at timestamptz,created_at timestamptz not null default now());
create table if not exists live_updates(id uuid primary key default gen_random_uuid(),live_session_id uuid not null references live_sessions(id) on delete cascade,body text not null,created_at timestamptz not null default now());
create table if not exists grievances(id uuid primary key default gen_random_uuid(),article_id uuid references articles(id) on delete set null,article_url text not null default '',complainant_name text not null,contact text not null,issue text not null,reason text not null default '',evidence_note text not null default '',urgent boolean not null default false,status text not null default 'received' check(status in('received','under_review','decision','action','reply','resolved')),decision_note text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists grievance_evidence(id uuid primary key default gen_random_uuid(),grievance_id uuid not null references grievances(id) on delete cascade,storage_path text not null,private boolean not null default true,created_at timestamptz not null default now());
create table if not exists compliance_tasks(id uuid primary key default gen_random_uuid(),title text not null,status text not null default 'pending',notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
-- RLS: private Phase-2 tables require authenticated owner. Public inserts only for analytics/grievance intake.
alter table audit_logs enable row level security; alter table analytics_events enable row level security; alter table social_distribution enable row level security; alter table reporters enable row level security; alter table live_sessions enable row level security; alter table live_updates enable row level security; alter table grievances enable row level security; alter table grievance_evidence enable row level security; alter table compliance_tasks enable row level security;
create or replace function public.jb_is_owner() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from user_roles where user_id=auth.uid() and role='owner') $$;
do $$ declare t text; begin foreach t in array array['audit_logs','social_distribution','reporters','live_sessions','live_updates','grievances','grievance_evidence','compliance_tasks'] loop execute format('drop policy if exists owner_all on %I',t); execute format('create policy owner_all on %I for all to authenticated using (public.jb_is_owner()) with check (public.jb_is_owner())',t); end loop; end $$;
drop policy if exists public_analytics_insert on analytics_events; create policy public_analytics_insert on analytics_events for insert to anon,authenticated with check(event_type in('view','share'));
drop policy if exists owner_analytics_read on analytics_events; create policy owner_analytics_read on analytics_events for select to authenticated using(public.jb_is_owner());
drop policy if exists public_grievance_insert on grievances; create policy public_grievance_insert on grievances for insert to anon,authenticated with check(status='received' and decision_note='');
-- Never put service-role/recovery secrets in frontend files.